// Generated by AI (UnitTest MCP)
//! Tenant-scoped Administration status, bounded claim recovery, adopted
//! Administration policies, and platform Snapshot requests for Bridge.
//!
//! ADR-0128 recognizes the hardened loopback developer profile
//! (`AdministrationApiState::tenant_id`) as the verified principal ADR-0119
//! decision 2 requires; it does not remove that decision's *policy* half.
//! Every privileged operation still needs an explicit, stored, unexpired,
//! unrevoked [`AdministrationPolicy`] naming it before it may run.
//! `Snapshot` is the first privileged operation with a real execution path
//! (platform-scoped only -- see `ackplane_server::snapshot_provider`'s own
//! doc comment for why tenant-scoped export needs its own separate
//! implementation). Export, recovery execution, and lifecycle purge remain
//! unimplemented and report so honestly.

use std::{
    sync::Arc,
    time::{SystemTime, UNIX_EPOCH},
};

use ackplane_server::administration_store::{
    AdministrationOperation, AdministrationPolicy, AdministrationScope, AdministrationStore,
    AdministrationStoreError, NewSnapshotReceipt, NewSnapshotRequest, PolicyAdoptionRequest,
    SnapshotOutcome, SnapshotReceipt,
};
use ackplane_server::fleet::{FleetStore, RepositoryFreshness};
use ackplane_server::snapshot_provider::{self, SnapshotProviderConfig, SnapshotProviderError};
use axum::{
    extract::{Path, State},
    http::StatusCode,
    response::Html,
    routing::{get, post},
    Json, Router,
};
use serde::{Deserialize, Serialize};
use tokio::sync::Mutex;

const ADMINISTRATION_PAGE: &str = include_str!("../static/administration.html");
/// ADR-0119 decision 2 bounds a policy's lifetime; this bounds how long a
/// caller may request one for in a single call, so a single adoption cannot
/// silently grant authority for years.
const MAX_POLICY_LIFETIME_SECONDS: u64 = 30 * 24 * 60 * 60;

/// Dependencies injected by the Bridge entry point when it merges the
/// Administration sub-router into the application.
#[derive(Clone)]
pub struct AdministrationApiState {
    pub fleet: Arc<FleetStore>,
    pub tenant_id: Arc<str>,
    pub administration: Arc<Mutex<AdministrationStore>>,
    /// `None` when `ACKPLANE_SNAPSHOT_DIR` is not configured -- Snapshot then
    /// reports `unavailable` rather than attempting to run `pg_dump` against
    /// a location nobody chose.
    pub snapshot: Option<Arc<SnapshotProviderConfig>>,
}

impl AdministrationApiState {
    pub fn new(
        fleet: Arc<FleetStore>,
        tenant_id: Arc<str>,
        administration: Arc<Mutex<AdministrationStore>>,
        snapshot: Option<Arc<SnapshotProviderConfig>>,
    ) -> Self {
        Self {
            fleet,
            tenant_id,
            administration,
            snapshot,
        }
    }
}

/// Builds the isolated Administration status sub-router.
pub fn administration_routes(state: AdministrationApiState) -> Router {
    Router::new()
        .route("/administration", get(administration_page))
        .route(
            "/api/v1/repositories/:repository_id/administration/status",
            get(repository_administration_status),
        )
        .route(
            "/api/v1/administration/policies",
            post(adopt_administration_policy),
        )
        .route(
            "/api/v1/administration/snapshots",
            post(request_platform_snapshot),
        )
        .route(
            "/api/v1/administration/snapshots/:request_id",
            get(platform_snapshot_receipt),
        )
        .with_state(state)
}

