async fn repository_administration_status(
    State(state): State<AdministrationApiState>,
    Path(repository_id): Path<String>,
) -> Result<Json<AdministrationStatusResponse>, StatusCode> {
    let detail = state
        .fleet
        .repository(state.tenant_id.as_ref(), &repository_id)
        .await
        .map_err(|error| {
            tracing::error!(%error, "Bridge Administration repository status query failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?
        .ok_or(StatusCode::NOT_FOUND)?;

    Ok(Json(AdministrationStatusResponse {
        repository_id: detail.repository_id,
        projection: ProjectionStatus {
            freshness: freshness_label(detail.freshness),
            ledger_stream_position: detail.ledger_stream_position,
            projection_stream_position: detail.projection_stream_position,
            projection_updated_at_seconds: unix_seconds(detail.projection_updated_at),
        },
        // The server's `DurabilityProfile` is process-local today. The Bridge
        // must not infer a durable claim from a missing published record.
        durability: DurabilityStatus {
            state: "not_reported",
            reason: "The deployment has not published a tenant-scoped durability report.",
        },
        capabilities: capabilities(&state).await,
    }))
}

async fn capabilities(state: &AdministrationApiState) -> Vec<AdministrationCapability> {
    let snapshot = match &state.snapshot {
        None => AdministrationCapability {
            operation: "snapshot",
            state: "unavailable",
            reason: "ACKPLANE_SNAPSHOT_DIR is not configured for this deployment.".to_string(),
        },
        Some(_) => {
            let mut administration = state.administration.lock().await;
            let active = administration
                .active_policy(
                    AdministrationOperation::Snapshot,
                    &AdministrationScope::Platform,
                    SystemTime::now(),
                )
                .await;
            match active {
                Ok(Some(_)) => AdministrationCapability {
                    operation: "snapshot",
                    state: "available",
                    reason: "A verified principal (ADR-0128) and an adopted platform policy authorize a Snapshot.".to_string(),
                },
                Ok(None) => AdministrationCapability {
                    operation: "snapshot",
                    state: "refused",
                    reason: "No adopted policy authorizes a platform Snapshot yet; adopt one via POST /api/v1/administration/policies (ADR-0119 decision 2).".to_string(),
                },
                Err(error) => {
                    tracing::error!(%error, "Bridge Administration policy lookup failed");
                    AdministrationCapability {
                        operation: "snapshot",
                        state: "unavailable",
                        reason: "The adopted-policy store could not be read.".to_string(),
                    }
                }
            }
        }
    };
    vec![
        AdministrationCapability {
            operation: "status_inspection",
            state: "available",
            reason: "Tenant-scoped projection and capability status are readable.".to_string(),
        },
        snapshot,
        AdministrationCapability {
            operation: "export",
            state: "refused",
            reason: "A verified principal now exists (ADR-0128); export itself is not implemented yet.".to_string(),
        },
        AdministrationCapability {
            operation: "claim_recovery",
            state: "available",
            reason: "Only an expired claim can be recovered; the next owner and a reason are recorded, and live claims refuse.".to_string(),
        },
        AdministrationCapability {
            operation: "recovery_inspection",
            state: "unavailable",
            reason: "An identified backup artifact and recovery evidence are required.".to_string(),
        },
        AdministrationCapability {
            operation: "lifecycle_purge",
            state: "refused",
            reason: "A verified principal now exists (ADR-0128); lifecycle purge itself is not implemented yet.".to_string(),
        },
    ]
}

#[derive(Deserialize)]
struct AdoptPolicyRequest {
    /// One of `snapshot`, `export`, `recovery_execution`, `lifecycle_purge`.
    operation: String,
    /// `platform`, or `tenant` with `tenant_id` set.
    scope: String,
    tenant_id: Option<String>,
    data_classification: String,
    retention_basis: String,
    idempotency_key: String,
    lifetime_seconds: u64,
}

#[derive(Serialize)]
struct AdoptPolicyResponse {
    policy_id: String,
    operation: &'static str,
    scope: &'static str,
    tenant_id: Option<String>,
    data_classification: String,
    retention_basis: String,
    adopted_by: String,
    effective_at_seconds: Option<u64>,
    expires_at_seconds: Option<u64>,
    idempotent_replay: bool,
}

async fn adopt_administration_policy(
    State(state): State<AdministrationApiState>,
    Json(request): Json<AdoptPolicyRequest>,
) -> Result<Json<AdoptPolicyResponse>, StatusCode> {
    let operation = parse_operation(&request.operation).ok_or(StatusCode::BAD_REQUEST)?;
    let scope = parse_scope(&request.scope, request.tenant_id).ok_or(StatusCode::BAD_REQUEST)?;
    if request.lifetime_seconds == 0 || request.lifetime_seconds > MAX_POLICY_LIFETIME_SECONDS {
        return Err(StatusCode::BAD_REQUEST);
    }
    let now = SystemTime::now();
    let policy_request = PolicyAdoptionRequest {
        operation,
        scope,
        data_classification: request.data_classification,
        retention_basis: request.retention_basis,
        adopted_by: state.tenant_id.to_string(),
        idempotency_key: request.idempotency_key,
        effective_at: now,
        expires_at: now + std::time::Duration::from_secs(request.lifetime_seconds),
    };

    let mut administration = state.administration.lock().await;
    let outcome = administration
        .adopt_policy(&policy_request)
        .await
        .map_err(administration_error_status)?;
    Ok(Json(policy_response(
        outcome.policy,
        outcome.idempotent_replay,
    )))
}

fn policy_response(policy: AdministrationPolicy, idempotent_replay: bool) -> AdoptPolicyResponse {
    AdoptPolicyResponse {
        policy_id: policy.policy_id,
        operation: operation_label(policy.operation),
        scope: scope_label(&policy.scope),
        tenant_id: policy.scope.tenant_id_owned(),
        data_classification: policy.data_classification,
        retention_basis: policy.retention_basis,
        adopted_by: policy.adopted_by,
        effective_at_seconds: unix_seconds(Some(policy.effective_at)),
        expires_at_seconds: unix_seconds(Some(policy.expires_at)),
        idempotent_replay,
    }
}

